"use client";
import TourCarousel from "../tour/tour-carousel";

const TopTravel = ({
  featuredTours,
  prices,
  priceLoading,
}: {
  featuredTours: any;
  prices: any;
  priceLoading: any;
}) => {
  const tours = featuredTours?.tours ?? [];

  if (tours.length === 0) return null;

  return (
    <section className="tw-bg-white tw-py-8 sm:tw-py-14 tw-font-display">
      <div className="tw-mx-auto tw-w-full tw-max-w-screen-xl tw-px-4">
        <div className="tw-mb-7">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Featured &amp; best-selling tours
          </h2>
          <p className="tw-mt-1.5 tw-mb-0 tw-max-w-[60ch] tw-text-sm tw-text-[#6b6577]">
            Tours travelers are loving this week — across every continent.
          </p>
        </div>

        <TourCarousel
          tours={tours}
          prices={prices}
          priceLoading={priceLoading}
        />
      </div>
    </section>
  );
};

export default TopTravel;
