"use client";
import React, { useEffect, useMemo, useRef, useState } from "react";
import styles from "./date-field.module.scss";

type DateFieldProps = {
  id: string;
  label: string;
  value: string; // "YYYY-MM-DD" or ""
  min?: string; // "YYYY-MM-DD"
  onChange: (v: string) => void;
};

const WEEKDAYS = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];
const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

const pad = (n: number) => String(n).padStart(2, "0");
const toISO = (y: number, m: number, d: number) =>
  `${y}-${pad(m + 1)}-${pad(d)}`;
const parseISO = (iso: string) => {
  const [y, m, d] = iso.split("-").map(Number);
  return { y, m: m - 1, d };
};

const formatDate = (iso: string) => {
  const { y, m, d } = parseISO(iso);
  return new Date(y, m, d).toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
};

const CalendarIcon = (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
    <rect x="3" y="4.5" width="18" height="16" rx="2.5" />
    <path d="M3 9.5h18M8 2.5v4M16 2.5v4" />
  </svg>
);

const ChevronLeft = (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
    <path d="m15 18-6-6 6-6" />
  </svg>
);

const ChevronRight = (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
    <path d="m9 18 6-6-6-6" />
  </svg>
);

const DateField = ({ id, label, value, min, onChange }: DateFieldProps) => {
  const rootRef = useRef<HTMLDivElement>(null);

  const todayISO = useMemo(() => {
    const t = new Date();
    return toISO(t.getFullYear(), t.getMonth(), t.getDate());
  }, []);
  const minISO = min || todayISO;
  const minParsed = parseISO(minISO);

  const [open, setOpen] = useState(false);
  const [viewYear, setViewYear] = useState(() => parseISO(value || minISO).y);
  const [viewMonth, setViewMonth] = useState(() => parseISO(value || minISO).m);

  // Close on outside click or Escape
  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  const toggle = () => {
    if (!open) {
      const p = parseISO(value || minISO);
      setViewYear(p.y);
      setViewMonth(p.m);
    }
    setOpen((o) => !o);
  };

  const shiftMonth = (delta: number) => {
    const d = new Date(viewYear, viewMonth + delta, 1);
    setViewYear(d.getFullYear());
    setViewMonth(d.getMonth());
  };

  const prevDisabled =
    viewYear * 12 + viewMonth <= minParsed.y * 12 + minParsed.m;

  const cells = useMemo(() => {
    const firstDow = (new Date(viewYear, viewMonth, 1).getDay() + 6) % 7;
    const days = new Date(viewYear, viewMonth + 1, 0).getDate();
    const arr: (number | null)[] = Array(firstDow).fill(null);
    for (let d = 1; d <= days; d++) arr.push(d);
    while (arr.length % 7 !== 0) arr.push(null);
    return arr;
  }, [viewYear, viewMonth]);

  return (
    <div className="hs-field" ref={rootRef}>
      <label className="hs-label" htmlFor={id}>
        {label}
      </label>

      <button
        id={id}
        type="button"
        className={`hs-control ${styles.trigger}`}
        onClick={toggle}
        aria-haspopup="dialog"
        aria-expanded={open}
      >
        <span className="hs-icon">{CalendarIcon}</span>
        <span className={value ? "hs-value" : "hs-placeholder"}>
          {value ? formatDate(value) : "Select date"}
        </span>
      </button>

      {open && (
        <div className={styles.popover} role="dialog" aria-label={label}>
          <div className={styles.header}>
            <button
              type="button"
              className={styles.navBtn}
              onClick={() => shiftMonth(-1)}
              disabled={prevDisabled}
              aria-label="Previous month"
            >
              {ChevronLeft}
            </button>
            <span className={styles.monthLabel}>
              {MONTHS[viewMonth]} {viewYear}
            </span>
            <button
              type="button"
              className={styles.navBtn}
              onClick={() => shiftMonth(1)}
              aria-label="Next month"
            >
              {ChevronRight}
            </button>
          </div>

          <div className={styles.weekdays}>
            {WEEKDAYS.map((w) => (
              <span key={w}>{w}</span>
            ))}
          </div>

          <div className={styles.grid}>
            {cells.map((d, i) => {
              if (d === null) return <span key={`e-${i}`} />;
              const iso = toISO(viewYear, viewMonth, d);
              const disabled = iso < minISO;
              const selected = iso === value;
              const isToday = iso === todayISO;
              const cls = [
                styles.day,
                selected ? styles.selected : "",
                isToday && !selected ? styles.today : "",
              ]
                .filter(Boolean)
                .join(" ");
              return (
                <button
                  key={iso}
                  type="button"
                  className={cls}
                  disabled={disabled}
                  onClick={() => {
                    onChange(iso);
                    setOpen(false);
                  }}
                >
                  {d}
                </button>
              );
            })}
          </div>

          <div className={styles.footer}>
            <button
              type="button"
              className={styles.linkBtn}
              onClick={() => {
                onChange("");
                setOpen(false);
              }}
              disabled={!value}
            >
              Clear
            </button>
            <button
              type="button"
              className={styles.linkBtn}
              onClick={() => setOpen(false)}
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default DateField;