import Image from "next/image";

const Categories = ({ tourCategories }: { tourCategories: any }) => {
  const categoryUrls = (slug: string) => {
    var url = "";

    switch (slug) {
      case "all-inclusive": {
        url = "worldwide-all-inclusive-tours";
        break;
      }
      case "healty-thermal-and-beauty": {
        url = "worldwide-healthy-thermal-and-beauty-tours";
        break;
      }
      case "combined-country": {
        url = "worldwide-combined-country-tours";
        break;
      }
      case "family-holidays": {
        url = "worldwide-family-holidays-tours";
        break;
      }
      case "national-park": {
        url = "worldwide-national-park-tours";
        break;
      }
      case "blue-cruise-ship": {
        url = "worldwide-blue-cruise-ship-tours";
        break;
      }
      case "sports-and-extreme": {
        url = "worldwide-adrenaline-and-extreme-sport-tours";
        break;
      }
      case "city": {
        url = "worldwide-city-sightseeing-tours";
        break;
      }
      case "indian-package": {
        url = "worldwide-indian-package-tours";
        break;
      }
      case "new-year-christmas": {
        url = "worldwide-new-year-and-christmas-tours";
        break;
      }
      case "anzac-day": {
        url = "worldwide-anzac-day-tours";
        break;
      }
      case "educational-tour": {
        url = "worldwide-student-tours";
        break;
      }
      case "gulet-cruise": {
        url = "worldwide-gulet-cruise-tours";
        break;
      }
      case "amusement-park-tickets": {
        url = "worldwide-amusement-park-tickets-tours";
        break;
      }
      case "special-days": {
        url = "worldwide-special-days-tours";
        break;
      }
      case "culture-historical": {
        url = "worldwide-culture-and-historical-tours";
        break;
      }
      case "luxury-tours": {
        url = "worldwide-luxury-travel-tours";
        break;
      }
      case "ticket": {
        url = "worldwide-ticket-tours";
        break;
      }
      case "culinary-wine-food-tasting": {
        url = "worldwide-culinary-wine-food-and-tasting-tours";
        break;
      }
      case "honeymoon": {
        url = "worldwide-honeymoon-tours";
        break;
      }
      case "religious": {
        url = "worldwide-religious-tours";
        break;
      }
      case "ski-holiday": {
        url = "worldwide-ski-tours";
        break;
      }
      case "events": {
        url = "worldwide-event-tours";
        break;
      }
      case "eco-tours": {
        url = "worldwide-eco-tours";
        break;
      }
      case "adventure": {
        url = "worldwide-adventure-tours";
        break;
      }
      case "stop-over": {
        url = "worldwide-stop-over-tours";
        break;
      }
      case "shopping": {
        url = "worldwide-shopping-tours";
        break;
      }
      case "women-art": {
        url = "worldwide-women-art-tours";
        break;
      }
      case "land-tour": {
        url = "worldwide-road-tours";
        break;
      }
      case "mice-package": {
        url = "worldwide-mice-tours";
        break;
      }
      default: {
        url = "worldwide-tours";
        break;
      }
    }

    return url;
  };

  const categories = tourCategories
    .filter((item: any) => item.slug !== "black-friday")
    .map((item: any) => {
      const tourCount = item.activities.reduce(
        (sum: number, element: any) => sum + element.count.tours.all,
        0,
      );
      return { ...item, tourCount };
    })
    .filter((item: any) => item.tourCount >= 100)
    .slice(0, 10);

  return (
    <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc] tw-font-display">
      <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
        <div className="tw-flex tw-flex-col sm:tw-flex-row tw-items-start sm:tw-items-end tw-justify-between tw-gap-2 sm:tw-gap-6 tw-mb-10">
          <div>
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Browse by what you love
            </h2>
            <p className="tw-mt-1.5 tw-mb-0 tw-max-w-[60ch] tw-text-sm tw-text-[#6b6577] tw-text-balance">
              From adrenaline to culture — pick a passion and explore tours
              built around it.
            </p>
          </div>
          <a
            href="/worldwide-tours"
            title="All Worldwide Tours"
            className="tw-shrink-0 tw-text-[14px] tw-font-semibold tw-text-[#854ec9] hover:tw-text-[#6a3da4] tw-no-underline tw-inline-flex tw-items-center tw-gap-1.5 tw-transition-colors tw-whitespace-nowrap"
          >
            All categories
            <span aria-hidden>→</span>
          </a>
        </div>

        <div className="tw-grid tw-grid-cols-2 sm:tw-grid-cols-3 lg:tw-grid-cols-5 tw-gap-4">
          {categories.map((item: any) => (
            <a
              key={item.slug}
              href={"/" + categoryUrls(item.slug)}
              title={"Worldwide " + item.name + " Tours"}
              className="group tw-no-underline tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] hover:tw-border-[#d8d2e1] hover:-tw-translate-y-0.5 hover:tw-shadow-lg tw-transition-all tw-duration-200"
            >
              <div className="tw-relative tw-aspect-[4/3] tw-overflow-hidden tw-bg-[#f3f1f7]">
                <Image
                  fill
                  src={item.image}
                  alt={item.name}
                  sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 17vw"
                  className="tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-[1.06]"
                  loading="lazy"
                />
                <span
                  aria-hidden
                  className="tw-absolute tw-inset-0 tw-pointer-events-none"
                  style={{
                    background:
                      "linear-gradient(180deg, rgba(20,16,28,0) 55%, rgba(20,16,28,0.18))",
                  }}
                />
              </div>
              <div className="tw-px-4 tw-pt-3.5 tw-pb-4">
                <p className="tw-text-[15px] tw-font-bold tw-leading-snug tw-text-[#14101c] group-hover:tw-text-[#854ec9] tw-transition-colors tw-m-0 tw-line-clamp-2">
                  {item.name}
                </p>
                <p className="tw-text-[13px] tw-text-[#5d556c] tw-mt-1 tw-mb-0">
                  {(Math.ceil(item.tourCount / 100) * 100).toLocaleString(
                    "en-US",
                  )}
                  <span className="tw-relative tw-top-[-1px]">+</span> tours
                  &amp; activities
                </p>
              </div>
            </a>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Categories;
